import * as THREE from './vendor/three.module.js';
import {FreeCamera} from './free-camera.js';
import {makeFaces,drawFlight} from './software-flight.js';
export class SoftwareViewer{constructor(host,onPick,cache){this.host=host;this.onPick=onPick;this.images=cache;this.canvas=document.createElement('canvas');this.canvas.tabIndex=0;this.canvas.setAttribute('aria-label','3D preview: drag to orbit, scroll to zoom, arrow keys to rotate');host.append(this.canvas);this.ctx=this.canvas.getContext('2d');this.canvas.style.touchAction='none';this.camera=new THREE.PerspectiveCamera(40,1,.05,5000);this.free=new FreeCamera(this.canvas,this.camera,()=>this.drawSoon(),()=>document.getElementById('cameraMode').click());let lastTick=performance.now();const tick=now=>{this.free.update((now-lastTick)/1000);lastTick=now;requestAnimationFrame(tick)};requestAnimationFrame(tick);this.yaw=.35;this.pitch=.12;this.zoom=1;this.pan=[0,0];let down,last,moved=false;this.canvas.oncontextmenu=e=>e.preventDefault();this.canvas.onpointerdown=e=>{if(this.free.active)return;down=[e.clientX,e.clientY,e.button];last=down;moved=false;this.canvas.setPointerCapture(e.pointerId)};this.canvas.onpointermove=e=>{if(this.free.active)return;if(!down)return;const dx=e.clientX-last[0],dy=e.clientY-last[1];if(Math.hypot(e.clientX-down[0],e.clientY-down[1])>3)moved=true;if(down[2]===2||e.shiftKey){this.pan[0]+=dx;this.pan[1]+=dy}else{this.yaw+=dx*.009;this.pitch=Math.max(-1.4,Math.min(1.4,this.pitch+dy*.007))}last=[e.clientX,e.clientY];this.drawSoon()};this.canvas.onpointerup=e=>{if(this.free.active){down=null;return}if(!moved&&this.p&&this.transform){const r=this.canvas.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top,{a,b,c,d,tx,ty}=this.transform,det=a*d-b*c;if(Math.abs(det)>.001){const u=Math.floor(((x-tx)*d-(y-ty)*c)/det),v=Math.floor(((y-ty)*a-(x-tx)*b)/det);if(u>=0&&v>=0&&u<this.p.width&&v<this.p.height)onPick(v*this.p.width+u)}}down=null};this.canvas.onwheel=e=>{e.preventDefault();if(this.free.active)return;this.zoom=Math.max(.15,Math.min(12,this.zoom*Math.exp(-e.deltaY*.001)));this.drawSoon()};this.canvas.onkeydown=e=>{if(this.free.active)return;if(e.key==='ArrowLeft')this.yaw-=.1;else if(e.key==='ArrowRight')this.yaw+=.1;else if(e.key==='ArrowUp')this.pitch=Math.min(1.4,this.pitch+.1);else if(e.key==='ArrowDown')this.pitch=Math.max(-1.4,this.pitch-.1);else return;e.preventDefault();this.drawSoon()};new ResizeObserver(()=>this.resize()).observe(host)}resize(){if(!this.host.clientWidth)return;this.canvas.width=this.host.clientWidth;this.canvas.height=this.host.clientHeight;this.drawSoon()}setFree(active){this.free.setActive(active);if(active)this.resetFlight();this.drawSoon()}resetFlight(){if(!this.p)return;const s=Math.max(this.p.width,this.p.height);this.camera.position.set(s*.3,this.p.height*.6,s*1.5);this.camera.lookAt(0,this.p.height/2,0);this.camera.updateMatrixWorld();this.free.speed=Math.max(8,s*.3)}setProject(p){this.p=p;this.faces=makeFaces(p);this.resetFlight();this.wall=document.createElement('canvas');this.wall.width=p.width*16;this.wall.height=p.height*16;const c=this.wall.getContext('2d');this.edges=[];p.cells.forEach((b,i)=>{if(b<0)return;const x=i%p.width,y=Math.floor(i/p.width),block=p.palette[b],im=this.images.get(block.texture);if(im)c.drawImage(im,x*16,y*16,16,16);else{c.fillStyle='rgb('+block.color+')';c.fillRect(x*16,y*16,16,16)}for(const [dx,dy]of[[-1,0],[1,0],[0,-1],[0,1]]){const nx=x+dx,ny=y+dy;if(nx<0||ny<0||nx>=p.width||ny>=p.height||p.cells[ny*p.width+nx]<0)this.edges.push({x,y,dx,dy,color:block.color})}});this.reset()}reset(){this.resetFlight();this.yaw=.35;this.pitch=.12;this.zoom=1;this.pan=[0,0];this.resize()}front(){if(this.free.active&&this.p){this.camera.position.set(0,this.p.height/2,Math.max(this.p.width,this.p.height)*1.5);this.camera.lookAt(0,this.p.height/2,0)}this.yaw=0;this.pitch=0;this.pan=[0,0];this.drawSoon()}drawSoon(){if(this.pending)return;this.pending=true;requestAnimationFrame(()=>{this.pending=false;this.draw()})}draw(){if(!this.p||!this.canvas.width)return;if(this.free.active){drawFlight(this.ctx,this.camera,this.p,this.faces,this.images);return}const ctx=this.ctx,W=this.canvas.width,H=this.canvas.height,p=this.p,s=Math.min((W-100)/p.width,(H-75)/p.height)*this.zoom,cy=Math.cos(this.yaw),sy=Math.sin(this.yaw),cp=Math.cos(this.pitch),sp=Math.sin(this.pitch);const project=(x,y,z)=>{x-=p.width/2;y-=p.height/2;let xx=x*cy+z*sy,zz=-x*sy+z*cy,yy=y*cp-zz*sp;return [W/2+xx*s+this.pan[0],H/2-yy*s+this.pan[1]]};ctx.fillStyle='#282b2d';ctx.fillRect(0,0,W,H);ctx.strokeStyle='#454b48';ctx.lineWidth=.6;const line=(a,b)=>{ctx.beginPath();ctx.moveTo(...a);ctx.lineTo(...b);ctx.stroke()};for(let k=-p.width;k<=p.width*2;k+=Math.max(1,Math.ceil(p.width/40))){line(project(k,0,-p.width),project(k,0,p.width));line(project(-p.width,0,k-p.width/2),project(p.width*2,0,k-p.width/2))}const z=cy*cp>=0?.5:-.5;for(const e of this.edges){const x=e.x,y=p.height-e.y;let corners,visible;if(e.dx){const ex=x+(e.dx>0?1:0);visible=e.dx*(-sy)*cp>0;corners=[[ex,y,-.5],[ex,y,.5],[ex,y-1,.5],[ex,y-1,-.5]]}else{const ey=y-(e.dy>0?1:0);visible=(-e.dy)*sp>0;corners=[[x,ey,-.5],[x+1,ey,-.5],[x+1,ey,.5],[x,ey,.5]]}if(!visible)continue;ctx.fillStyle='rgb('+e.color.map(v=>Math.round(v*(e.dy<0?.95:.62)))+')';ctx.beginPath();corners.map(c=>project(...c)).forEach((v,i)=>i?ctx.lineTo(...v):ctx.moveTo(...v));ctx.closePath();ctx.fill()}const tl=project(0,p.height,z),tr=project(p.width,p.height,z),bl=project(0,0,z),a=(tr[0]-tl[0])/p.width,b=(tr[1]-tl[1])/p.width,c=(bl[0]-tl[0])/p.height,d=(bl[1]-tl[1])/p.height;this.transform={a,b,c,d,tx:tl[0],ty:tl[1]};ctx.save();ctx.setTransform(a/16,b/16,c/16,d/16,tl[0],tl[1]);ctx.imageSmoothingEnabled=false;ctx.drawImage(this.wall,0,0);ctx.restore();ctx.fillStyle='#8295ae';ctx.font='9px sans-serif';/* no extra overlay */}}
